Bytes load(const std::filesystem::path&p,const std::string&hash,std::size_t cap){auto n=std::filesystem::file_size(p);check(n<=cap,"file capacity");std::ifstream f(p,std::ios::binary);Bytes b(n);f.read(reinterpret_cast<char*>(b.data()),std::streamsize(n));check(bool(f)&&f.peek()==EOF,"exact file length");check(picosha2::hash256_hex_string(b)==hash,"fixture SHA");return b;}
struct Reader{std::span<const std::uint8_t>b;std::size_t at{};auto take(std::size_t n){check(at<=b.size()&&n<=b.size()-at,"fixture truncated");auto v=b.subspan(at,n);at+=n;return v;}U u(){auto v=take(4);return U(v[0])|(U(v[1])<<8)|(U(v[2])<<16)|(U(v[3])<<24);}std::uint64_t u64(){auto lo=u();return std::uint64_t(lo)|(std::uint64_t(u())<<32);}Bytes bytes(std::size_t n){auto v=take(n);return{v.begin(),v.end()};}std::string text(){auto n=u();check(n<=256,"text extent");auto v=take(n);return{v.begin(),v.end()};}void end(){check(at==b.size(),"fixture trailing");}};
