bool known(const Case&c,U a,U n){for(U i=0;i<n;++i)if(!std::any_of(c.known.begin(),c.known.end(),[&](auto r){return r.first<=a+i&&a+i<r.second;}))return false;return true;}
template<class T>std::optional<T> field(const Case&c,const Raw&r,U a,U o,U n){if(!known(c,addr[a]+o,n))return{};auto v=word(r[a],o,n);if constexpr(std::is_same_v<T,std::int8_t>)return std::bit_cast<std::int8_t>(std::uint8_t(v));else return static_cast<T>(v);}
