 if(auto v=field<U>(c,r,15,0x400,4)){check(*v==0||*v==addr[15]+0x800,"record binding");x.entries[0].record=*v?oi::Link<oi::RecordIndex>{oi::RecordIndex{0}}:oi::Link<oi::RecordIndex>{oq::Absent{}};}
 for(auto[o,dest,ix]:{std::tuple{0x84cU,&x.records[0].field4c,0U},std::tuple{0x8b4U,&x.records[0].fieldb4,1U}})if(auto v=field<U>(c,r,15,o,4)){check(*v==0||*v==addr[15]+(ix?0x1000:0xc00),"parameter binding");*dest=*v?oi::Link<oi::ParameterIndex>{oi::ParameterIndex{ix}}:oi::Link<oi::ParameterIndex>{oq::Absent{}};}
