bool same_registry(const Registry&a,const Registry&b){if(a.table!=b.table)return false;for(U i=0;i<a.entries.size();++i)if(a.entries[i].record!=b.entries[i].record)return false;for(U i=0;i<a.records.size();++i)if(a.records[i].field4c!=b.records[i].field4c||a.records[i].fieldb4!=b.records[i].fieldb4)return false;for(U i=0;i<a.parameters.size();++i)if(a.parameters[i].field30_bits!=b.parameters[i].field30_bits||a.parameters[i].field80_bits!=b.parameters[i].field80_bits)return false;for(U i=0;i<a.overrides.size();++i)if(a.overrides[i].field_e4_bits!=b.overrides[i].field_e4_bits)return false;return true;}
