 f.object20=field<std::int8_t>(x,r,4,0x20,1);f.object21=field<std::int8_t>(x,r,4,0x21,1);f.manager={field<std::uint8_t>(x,r,5,0xad24,1),field<U>(x,r,5,0xad50,4),field<U>(x,r,5,0xad64,4),field<std::int8_t>(x,r,5,0xad20,1)};
