std::size_t calls(const Case&c,U pc,const Call*scope=nullptr){return std::count_if(c.calls.begin(),c.calls.end(),[&](const auto&a){return a.pc==pc&&(!scope||(a.start>=scope->start&&a.end<=scope->end));});}
