 s=call(c,0x68da18);check(e.interaction.has_value()==bool(s),"interaction presence");if(s){++interactions;const auto&a=e.interaction->effects;check(a.slots_examined==pcs_count(c,0x68da4c,s),"interaction slots");check(a.enabled_queries==calls(c,0x911e48,s)&&a.category_queries==calls(c,0x94d0e0,s)&&a.provider_queries==calls(c,0x6881d8,s)&&a.sphere_queries==calls(c,0x20c044,s),"interaction counts");check(e.interaction->selected.has_value()==(s->value!=0),"selected presence");if(s->value)check(e.interaction->selected->value==index(s->value,addr[12],0x1000,4),"selected identity");}
